      SUBROUTINE DSOLENCC     CALCULATES THE PARTIAL DERIVATIVES OF THE FIRST-ORDER MATRIX C     ELEMENTS WITH RESPECT TO THE PARAMETERS DESCRIBING A SOLENOIDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      INTEGER        IB, IK, J1      REAL           DBC-------------------------------------------------------------------------------C      CS = COS(KL)      SN = SIN(KL)      IF (JV .EQ. 1) GO TO 10      IF (JV .EQ. 2) GO TO 20      IF (JV .EQ. 3) GO TO 20      GO TO 50CC     LENGTH OF SOLENOID VARIEDC   10 LV = DPARM*UNITI(8)      RV(1,1) = - 0.5*KO*SN*LV      RV(2,2) = RV(1,1)      RV(1,2) = CS*LV      RV(2,1) = - 0.25*KO**2*CS*LV      RV(1,3) = 0.5*KO*CS*LV      RV(2,4) = RV(1,3)      RV(1,4) = SN*LV      RV(2,3) = - 0.25*KO**2*SN*LV      GO TO 50CC     FIELD OF SOLENOID VARIEDC   20 IB = IPTOJ(2)      IK = IPTOJ(3)      IF (IB .NE. 0) DB = DPARM*L*UNITI(9)/PREF      IF (IK .NE. 0) DB = 2.0*DPARM*UNITI(7)      RV(1,1) = - 0.5*DB*SN      RV(2,2) = RV(1,1)      RV(1,2) = DB*( - SN/KL + CS)/KO      RV(2,1) = - 0.25*DB*(SN/L + KO*CS)      RV(1,3) = 0.5*DB*CS      RV(2,4) = RV(1,3)      RV(1,4) = DB*(SN - (1.0 - CS)/KL)/KO      RV(2,3) = - 0.25*DB*(KO*SN + (1.0 - CS)/L)CC     K FACTOR OF SOLENOID VARIEDC   50 CONTINUE      DO 55 J = 3, 4      DO 55 J1 = 1, 2      RV(J,J1) = - RV(J-2,J1+2)   55 CONTINUE      DO 60 J = 1, 2      DO 60 J1 = 1, 2      RV(J+2,J1+2) = RV(J,J1)   60 CONTINUE      RETURN      END